import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        Scanner in = new Scanner(System.in);
        while (in.hasNextLine()) {
            String member = in.nextLine().trim();
            int diskon;
            switch (member) {
                case "gold":
                    diskon = 20;
                case "silver":
                    diskon = 10;
                    break;
                default:
                    diskon = 0;
            }
            System.out.println(member + ": " + diskon + "%");
        }
    }
}

