import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        Scanner in = new Scanner(System.in);
        while (in.hasNextLine()) {
            String member = in.nextLine().trim();
            int diskon = switch (member) {
                case "gold" -> 20;
                case "silver" -> 10;
                default -> 0;
            };
            System.out.println(member + ": " + diskon + "%");
        }
    }
}
